package alicanteweb.erp.controller;  import alicanteweb.erp.entities.EmpresaConfig; import alicanteweb.erp.entities.Factura; import alicanteweb.erp.entities.VerifactuEvidence; import alicanteweb.erp.service.EmpresaConfigService; import alicanteweb.erp.service.FacturaService; import alicanteweb.erp.service.VerifactuEvidenceService; import alicanteweb.erp.service.VerifactuService; import alicanteweb.erp.ui.DialogUtils; import javafx.application.Platform; import javafx.beans.property.SimpleStringProperty; import javafx.collections.FXCollections; import javafx.collections.ObservableList; import javafx.concurrent.Task; import javafx.fxml.FXML; import javafx.scene.control.Button; import javafx.scene.control.CheckBox; import javafx.scene.control.Label; import javafx.scene.control.ProgressIndicator; import javafx.scene.control.TableColumn; import javafx.scene.control.TableView; import javafx.scene.control.TextField; import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.stereotype.Controller;  import java.time.ZoneId; import java.time.format.DateTimeFormatter; import java.util.ArrayList; import java.util.List;  @Controller public class VerifactuController {     private static final Logger log = LoggerFactory.getLogger(VerifactuController.class);     private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm");      @FXML private Label lblEstado;     @FXML private CheckBox chkHabilitado;    @FXML private TextField txtNif;     @FXML private Label lblInfo;      @FXML private Button btnEnviar;     @FXML private Button btnGuardar;     @FXML private Button btnProbar;     @FXML private ProgressIndicator progressIndicator;      @FXML private TableView<VerifactuEvidence> tableEnvios;     @FXML private TableColumn<VerifactuEvidence, String> colFecha;     @FXML private TableColumn<VerifactuEvidence, String> colFactura;     @FXML private TableColumn<VerifactuEvidence, String> colCliente;     @FXML private TableColumn<VerifactuEvidence, String> colImporte;     @FXML private TableColumn<VerifactuEvidence, String> colEstado;     @FXML private TableColumn<VerifactuEvidence, String> colReferencia;     @FXML private TableColumn<VerifactuEvidence, String> colMensaje;      @FXML private TextField txtBuscar;     @FXML private Label lblTotal;      private final VerifactuService verifactuService;     private final FacturaService facturaService;     private final EmpresaConfigService empresaConfigService;     private final VerifactuEvidenceService evidenceService;     private final ObservableList<VerifactuEvidence> listaEnvios = FXCollections.observableArrayList();     private boolean verifactuHabilitado = false;      public VerifactuController(VerifactuService verifactuService,                                FacturaService facturaService,                                EmpresaConfigService empresaConfigService,                                VerifactuEvidenceService evidenceService) {         this.verifactuService = verifactuService;         this.facturaService = facturaService;         this.empresaConfigService = empresaConfigService;         this.evidenceService = evidenceService;     }      @FXML     public void initialize() {         log.info("Inicializando VerifactuController");         configurarTabla();         if (txtBuscar != null) {             txtBuscar.textProperty().addListener((obs, oldValue, newValue) -> filtrarEnvios(newValue));         }         cargarConfiguracion();         cargarDatos();     }      private void configurarTabla() {         colFecha.setCellValueFactory(cellData -> {             VerifactuEvidence evidencia = cellData.getValue();             String fecha = "-";             if (evidencia.getFechaGeneracionRegistro() != null) {                 fecha = DATE_FORMATTER.withZone(ZoneId.systemDefault()).format(evidencia.getFechaGeneracionRegistro());             } else if (evidencia.getFechaEnvio() != null) {                 fecha = DATE_FORMATTER.withZone(ZoneId.systemDefault()).format(evidencia.getFechaEnvio());             } else if (evidencia.getFechaEmision() != null) {                 fecha = DATE_FORMATTER.withZone(ZoneId.systemDefault()).format(evidencia.getFechaEmision());             }             return new SimpleStringProperty(fecha);         });          colFactura.setCellValueFactory(cellData -> new SimpleStringProperty(             cellData.getValue().getNumero() != null ? cellData.getValue().getNumero() : "-"         ));          colCliente.setCellValueFactory(cellData -> {             VerifactuEvidence evidencia = cellData.getValue();             String cliente = "-";             try {                 long facturaId = Long.parseLong(evidencia.getFacturaId());                 var factura = facturaService.findById(facturaId);                 if (factura.isPresent() && factura.get().getCliente() != null) {                     cliente = factura.get().getCliente().getNombre();                 }             } catch (Exception ignored) {             }             return new SimpleStringProperty(cliente);         });          colImporte.setCellValueFactory(cellData -> {             VerifactuEvidence evidencia = cellData.getValue();             String importe = "0.00 EUR";             try {                 long facturaId = Long.parseLong(evidencia.getFacturaId());                 var factura = facturaService.findById(facturaId);                 if (factura.isPresent() && factura.get().getTotal() != null) {                     importe = String.format("%.2f EUR", factura.get().getTotal());                 }             } catch (Exception ignored) {             }             return new SimpleStringProperty(importe);         });          colEstado.setCellValueFactory(cellData -> new SimpleStringProperty(             cellData.getValue().getEstado() != null ? cellData.getValue().getEstado() : "-"         ));          colReferencia.setCellValueFactory(cellData -> new SimpleStringProperty(             cellData.getValue().getCodigoRespuestaAEAT() != null                 ? cellData.getValue().getCodigoRespuestaAEAT()                 : (cellData.getValue().getHuellaRegistro() != null ? cellData.getValue().getHuellaRegistro() : "-")         ));          colMensaje.setCellValueFactory(cellData -> new SimpleStringProperty(             cellData.getValue().getErrorMessage() != null ? cellData.getValue().getErrorMessage() : ""         ));          tableEnvios.setItems(listaEnvios);     }      private void cargarConfiguracion() {         try {             empresaConfigService.getConfiguracionActiva().ifPresent(cfg -> {                 verifactuHabilitado = Boolean.TRUE.equals(cfg.getVerifactuHabilitado());                 if (chkHabilitado != null) {                     chkHabilitado.setSelected(verifactuHabilitado);                 }                 if (txtNif != null && cfg.getVerifactuNifEmisor() != null) {                     txtNif.setText(cfg.getVerifactuNifEmisor());                 }             });         } catch (Exception e) {             log.warn("No se pudo cargar configuracion de empresa para Verifactu: {}", e.getMessage());         }         actualizarEstado();     }      private void actualizarEstado() {         if (lblEstado == null) {             return;         }         if (verifactuHabilitado) {             lblEstado.setText(verifactuService.isAeatAvailable() ? "â— Activo y listo" : "â— Configurado sin AEAT disponible");             lblEstado.setStyle("-fx-text-fill: #198754; -fx-font-weight: bold;");         } else {             lblEstado.setText("â— Deshabilitado");             lblEstado.setStyle("-fx-text-fill: #dc3545; -fx-font-weight: bold;");         }     }      private void cargarDatos() {         try {             List<VerifactuEvidence> evidencias = evidenceService.findAll();             listaEnvios.clear();             listaEnvios.addAll(evidencias);              int pendientes = 0;             for (Factura factura : facturaService.findAll()) {                 if ("REVISION".equalsIgnoreCase(factura.getEstado()) && !Boolean.TRUE.equals(factura.getVerifactuEnviada())) {                     pendientes++;                 }             }              if (lblTotal != null) {                 lblTotal.setText(listaEnvios.size() + " registros");             }             if (lblInfo != null) {                 lblInfo.setText(pendientes + " facturas en revision pendientes de emitir");             }         } catch (Exception e) {             log.error("Error cargando datos de Verifactu", e);             DialogUtils.showError("Error al cargar datos: " + e.getMessage());         }     }      private void filtrarEnvios(String busqueda) {         if (busqueda == null || busqueda.isBlank()) {             tableEnvios.setItems(listaEnvios);         } else {             String query = busqueda.toLowerCase();             tableEnvios.setItems(listaEnvios.filtered(e ->                 (e.getNumero() != null && e.getNumero().toLowerCase().contains(query)) ||                 (e.getEstado() != null && e.getEstado().toLowerCase().contains(query)) ||                 (e.getTipoRegistro() != null && e.getTipoRegistro().toLowerCase().contains(query)) ||                 (e.getFacturaId() != null && e.getFacturaId().toLowerCase().contains(query))             ));         }         if (lblTotal != null) {             lblTotal.setText(tableEnvios.getItems().size() + " registros");         }     }      @FXML     public void onCambiarEstado() {         verifactuHabilitado = chkHabilitado.isSelected();         actualizarEstado();     }      @FXML     public void onGuardar() {         String nif = txtNif != null ? txtNif.getText() : "";         if (verifactuHabilitado && (nif == null || nif.isBlank())) {             DialogUtils.showWarning("Por favor, introduce el NIF del emisor.");             return;         }          try {             EmpresaConfig cfg = empresaConfigService.getConfiguracionActiva().orElseGet(EmpresaConfig::new);             cfg.setVerifactuHabilitado(verifactuHabilitado);             if (nif != null && !nif.isBlank()) {                 cfg.setVerifactuNifEmisor(nif);             }             empresaConfigService.save(cfg);             actualizarEstado();             DialogUtils.showSuccess("Configuracion guardada.\nLa ruta y password del certificado se gestionan por properties o variables de entorno.");         } catch (Exception e) {             log.error("Error guardando configuracion de Verifactu", e);             DialogUtils.showError("Error al guardar: " + e.getMessage());         }     }      @FXML     public void onProbar() {         if (!verifactuHabilitado) {             DialogUtils.showWarning("Verifactu esta deshabilitado.");             return;         }          if (verifactuService.isAeatAvailable()) {             DialogUtils.showSuccess("AEAT y certificado estan disponibles para emitir.");         } else {             DialogUtils.showWarning("El servicio no esta listo para emitir contra AEAT.\nRevisa keystore, alias, password y verifactu.aeat.enabled.");         }         actualizarEstado();     }      @FXML     public void onEnviar() {         if (!verifactuHabilitado) {             DialogUtils.showWarning("Verifactu esta deshabilitado. Activalo primero.");             return;         }          if (!DialogUtils.showConfirm("Â¿Deseas emitir a AEAT todas las facturas en revision pendientes?")) {             return;         }          List<Factura> pendientes = new ArrayList<>();         for (Factura factura : facturaService.findAll()) {             if ("REVISION".equalsIgnoreCase(factura.getEstado()) && !Boolean.TRUE.equals(factura.getVerifactuEnviada())) {                 pendientes.add(factura);             }         }          if (pendientes.isEmpty()) {             DialogUtils.showInfo("No hay facturas en revision pendientes de emitir.");             return;         }          setUiBusy(true, "Emitiendo facturas a AEAT...");          Task<Void> task = new Task<>() {             @Override             protected Void call() {                 int enviados = 0;                 int errores = 0;                 for (int i = 0; i < pendientes.size(); i++) {                     Factura factura = pendientes.get(i);                     try {                         facturaService.aprobarYEmitir(factura.getId());                         enviados++;                     } catch (Exception e) {                         errores++;                         log.error("Error emitiendo factura {}", factura.getNumero(), e);                     }                     updateProgress(i + 1, pendientes.size());                 }                  final int totalEnviados = enviados;                 final int totalErrores = errores;                 Platform.runLater(() -> {                     cargarDatos();                     DialogUtils.showSuccess(String.format(                         "Proceso completado:\n\nEmitidas: %d\nErrores: %d",                         totalEnviados,                         totalErrores                     ));                 });                 return null;             }         };          if (progressIndicator != null) {             progressIndicator.progressProperty().bind(task.progressProperty());         }          task.setOnSucceeded(ev -> setUiBusy(false, "Proceso finalizado"));         task.setOnFailed(ev -> setUiBusy(false, "Error durante la emision"));         task.setOnCancelled(ev -> setUiBusy(false, "Emision cancelada"));          Thread thread = new Thread(task, "verifactu-emision-thread");         thread.setDaemon(true);         thread.start();     }      @FXML     public void onVerificar() {         VerifactuEvidence selected = tableEnvios.getSelectionModel().getSelectedItem();         if (selected == null) {             DialogUtils.showWarning("Selecciona un registro para verificar.");             return;         }         VerifactuEvidence evidencia = evidenceService.verificarEstadoAEAT(selected.getId());         cargarDatos();         DialogUtils.showInfo("Estado actual: " + evidencia.getEstado());     }      @FXML     public void onRefresh() {         cargarDatos();     }      @FXML     public void onVerDetalles() {         VerifactuEvidence selected = tableEnvios.getSelectionModel().getSelectedItem();         if (selected == null) {             DialogUtils.showWarning("Por favor, selecciona un registro");             return;         }          String detalle = "DETALLE DE REGISTRO VERIFACTU\n\n" +             "Factura: " + (selected.getNumero() != null ? selected.getNumero() : selected.getFacturaId()) + "\n" +             "Tipo registro: " + (selected.getTipoRegistro() != null ? selected.getTipoRegistro() : "-") + "\n" +             "Fecha generacion: " + (selected.getFechaGeneracionRegistro() != null ? DATE_FORMATTER.withZone(ZoneId.systemDefault()).format(selected.getFechaGeneracionRegistro()) : "-") + "\n" +             "Estado: " + (selected.getEstado() != null ? selected.getEstado() : "-") + "\n" +             "Referencia: " + (selected.getCodigoRespuestaAEAT() != null ? selected.getCodigoRespuestaAEAT() : selected.getHuellaRegistro()) + "\n" +             "Error: " + (selected.getErrorMessage() != null ? selected.getErrorMessage() : "");          DialogUtils.showInfo(detalle);     }      @FXML     public void onReenviar() {         VerifactuEvidence selected = tableEnvios.getSelectionModel().getSelectedItem();         if (selected == null) {             DialogUtils.showWarning("Selecciona un registro.");             return;         }         evidenceService.reenviarEvidencia(selected.getId());         cargarDatos();         DialogUtils.showSuccess("Reintento registrado.");     }      @FXML     public void onExportar() {         DialogUtils.showWarning("La exportacion detallada aun no esta implementada.");     }      private void setUiBusy(boolean busy, String infoText) {         if (btnEnviar != null) btnEnviar.setDisable(busy);         if (btnGuardar != null) btnGuardar.setDisable(busy);         if (btnProbar != null) btnProbar.setDisable(busy);         if (progressIndicator != null) {             if (!busy) {                 progressIndicator.progressProperty().unbind();             }             progressIndicator.setVisible(busy);             progressIndicator.setProgress(busy ? ProgressIndicator.INDETERMINATE_PROGRESS : 0);         }         if (lblInfo != null) {             lblInfo.setText(infoText);         }     } } 